<script setup>
import {ref,computed,onMounted} from 'vue'
import {route,go} from '../router.js'
import {api,money,orderStates,payStates} from '../api/client.js'
import Pager from '../components/Pager.vue'
import OrderDetail from '../components/OrderDetail.vue'
const tab=computed(()=>route.value.split('/')[2]),titles={menu:'今天，想吃点什么？',cart:'购物车与结算',orders:'我的订单',addresses:'收货地址'}
const categories=ref([]),category=ref(null),items=ref([]),cart=ref([]),addresses=ref([]),addressId=ref(''),remark=ref(''),payMethod=ref(1),shop=ref(0),loading=ref(false),busy=ref(false),notice=ref(''),page=ref(1),total=ref(0),status=ref(''),detail=ref(null),choice=ref(null),flavors=ref({}),newAddress=ref(false)
const address=ref({consignee:'',phone:'',provinceName:'',cityName:'',districtName:'',detail:''}),sum=computed(()=>cart.value.reduce((s,c)=>s+Math.round(Number(c.amount)*100)*c.number,0)/100)
const get=(p,q)=>api('user','GET',p,undefined,q)
async function load(){loading.value=true;try{if(tab.value==='menu'){const [a,b,s]=await Promise.all([get('/category/list',{type:1}),get('/category/list',{type:2}),get('/shop/status')]);categories.value=[...(a||[]).map(c=>({...c,type:1})),...(b||[]).map(c=>({...c,type:2}))];shop.value=s;if(categories.value.length)await select(categories.value[0])}else if(tab.value==='cart'){const [a,b,s]=await Promise.all([get('/shoppingCart/list'),get('/addressBook/list'),get('/shop/status')]);cart.value=a||[];addresses.value=b||[];shop.value=s;addressId.value=b?.[0]?.id||''}else if(tab.value==='addresses')addresses.value=await get('/addressBook/list')||[];else{const result=await get('/order/historyOrders',{page:page.value,pageSize:10,status:status.value});items.value=result.records||[];total.value=result.total||0}}catch{}finally{loading.value=false}}
let sequence=0
async function select(c){category.value=c;const id=++sequence;try{const data=await get(c.type===1?'/dish/list':'/setmeal/list',{categoryId:c.id});if(id===sequence)items.value=data||[]}catch{if(id===sequence)items.value=[]}}
onMounted(load)
async function act(fn,message){if(busy.value)return false;busy.value=true;try{await fn();notice.value=message||'操作成功';return true}catch{return false}finally{busy.value=false}}
function options(f){try{const v=JSON.parse(f.value);return Array.isArray(v)?v:[]}catch{return String(f.value||'').split(',')}}
function choose(item){choice.value={...item,type:category.value.type};flavors.value={};(item.flavors||[]).forEach(f=>flavors.value[f.name]=options(f)[0]||'')}
function cartBody(item){return {dishId:item.dishId,setmealId:item.setmealId,dishFlavor:item.dishFlavor}}
async function add(){const i=choice.value;const data={...(i.type===1?{dishId:i.id}:{setmealId:i.id}),name:i.name,image:i.image,amount:i.price,number:1,dishFlavor:Object.entries(flavors.value).map(([k,v])=>k+':'+v).join(';')};if(await act(()=>api('user','POST','/shoppingCart/add',data),'已加入购物车'))choice.value=null}
async function change(c,kind){if(await act(()=>api('user','POST','/shoppingCart/'+kind,cartBody(c))))cart.value=await get('/shoppingCart/list')||[]}
async function cleanCart(){if(confirm('清空购物车？')&&await act(()=>api('user','DELETE','/shoppingCart/clean')))await load()}
async function submit(){if(await act(()=>api('user','POST','/order/submit',{addressBookId:addressId.value,payMethod:payMethod.value,remark:remark.value}),'下单成功'))go('/user/orders')}
async function saveAddress(){if(await act(()=>api('user','POST','/addressBook',address.value),'地址已保存')){newAddress.value=false;await load()}}
async function orderAction(row,kind){if(kind==='cancel'&&!confirm('确认取消此订单？'))return;if(await act(()=>api('user',kind==='cancel'?'PUT':'POST','/order/'+kind+'/'+row.id),kind==='repetition'?'已加入购物车':'操作成功')){if(kind==='repetition')go('/user/cart');else await load()}}
async function view(row){try{detail.value=await get('/order/orderDetail/'+row.id)}catch{}}
</script>
<template><div class="page-title"><div><span class="eyebrow">FRESH FOOD · GOOD MOOD</span><h1>{{titles[tab]}}</h1></div><button :disabled="loading" @click="load">↻ 刷新</button></div><p v-if="notice" class="success" role="status">{{notice}}</p><p v-if="loading" role="status">正在加载…</p>
<template v-if="tab==='menu'"><section class="hero food-hero"><div><span class="badge">{{shop===1?'营业中 · 欢迎下单':'店铺休息中'}}</span><h2>热爱生活，<br>从好好吃饭开始。</h2><p>现点现做，把新鲜送到你身边。</p></div><span class="hero-food">🍲</span></section><div class="catalog"><nav class="categories"><button v-for="c in categories" :key="c.type+'-'+c.id" :class="{primary:category?.id===c.id&&category?.type===c.type}" @click="select(c)">{{c.name}} <small>{{c.type===2?'套餐':''}}</small></button></nav><div class="food-grid"><article v-for="item in items" :key="item.id" class="food-card"><img v-if="item.image" :src="item.image" :alt="item.name"><div v-else class="food-placeholder">{{category?.type===2?'🍱':'🍜'}}</div><div class="food-info"><h3>{{item.name}}</h3><p class="muted">{{item.description||'精心烹制，新鲜美味'}}</p><div class="section-title"><strong class="price">{{money(item.price)}}</strong><button class="primary" :disabled="shop!==1" @click="choose(item)">＋ 加购</button></div></div></article><p v-if="!items.length&&!loading" class="empty">当前分类暂无在售商品</p></div></div><a class="cart-float" href="#/user/cart">🛒 查看购物车 / 去结算 →</a></template>
<template v-else-if="tab==='cart'"><section class="card"><div class="section-title"><h2>已选商品</h2><button :disabled="!cart.length||busy" @click="cleanCart()">清空</button></div><div v-for="c in cart" :key="c.id" class="line"><span><b>{{c.name}}</b><small class="block">{{c.dishFlavor}}</small></span><div class="actions"><b>{{money(c.amount)}}</b><button :disabled="busy" @click="change(c,'sub')" aria-label="减少数量">−</button>{{c.number}}<button :disabled="busy" @click="change(c,'add')" aria-label="增加数量">＋</button></div></div><p v-if="!cart.length" class="empty">购物车还是空的，<a href="#/user/menu">去选点好吃的 →</a></p></section><form v-if="cart.length" class="card checkout" @submit.prevent="submit"><h2>配送信息</h2><label>收货地址<select v-model="addressId" required><option value="" disabled>请选择收货地址</option><option v-for="a in addresses" :key="a.id" :value="a.id">{{a.consignee}} {{a.phone}} · {{a.provinceName}}{{a.cityName}}{{a.districtName}}{{a.detail}}</option></select></label><a href="#/user/addresses">＋ 新增地址</a><label>支付方式<select v-model.number="payMethod"><option :value="1">微信支付</option><option :value="2">支付宝</option></select></label><p class="muted">当前后端提供模拟支付，下单后可在订单列表操作；需后端开启模拟支付功能。</p><label>订单备注<textarea v-model="remark" maxlength="200" placeholder="口味、配送等特殊要求"></textarea></label><div class="section-title"><h2>合计 {{money(sum)}}</h2><button class="primary" :disabled="busy||shop!==1||!addressId">{{busy?'提交中…':shop!==1?'店铺休息中':'提交订单'}}</button></div></form></template>
<template v-else-if="tab==='addresses'"><button class="primary" @click="newAddress=true">＋ 新增收货地址</button><div class="address-grid"><article v-for="a in addresses" :key="a.id" class="card"><h3>{{a.consignee}} <small>{{a.phone}}</small></h3><p>{{a.provinceName}}{{a.cityName}}{{a.districtName}}{{a.detail}}</p></article></div><p v-if="!addresses.length&&!loading" class="empty">还没有收货地址，请先添加</p></template>
<template v-else><form class="toolbar" @submit.prevent="page=1;load()"><select v-model="status" aria-label="订单状态"><option value="">全部订单</option><option v-for="(s,i) in orderStates.slice(1)" :key="i" :value="i+1">{{s}}</option></select><button class="primary">筛选</button></form><article v-for="o in items" :key="o.id" class="card order-card"><div class="section-title"><small class="muted">{{o.orderTime}} · {{o.number}}</small><span class="badge">{{orderStates[o.status]}}</span></div><div class="section-title"><div><h3>苍穹外卖</h3><p>{{o.address}}</p><span class="muted">{{payStates[o.payStatus]}}</span></div><h2>{{money(o.amount)}}</h2></div><div class="actions"><button @click="view(o)">订单详情</button><button v-if="[1,2].includes(o.status)" :disabled="busy" @click="orderAction(o,'cancel')">取消订单</button><button v-if="o.status===1&&o.payStatus===0" class="primary" :disabled="busy" @click="orderAction(o,'mock-pay')">模拟支付</button><button :disabled="busy" @click="orderAction(o,'repetition')">再来一单</button></div></article><p v-if="!items.length&&!loading" class="empty">暂无订单，<a href="#/user/menu">去点餐 →</a></p><Pager :page="page" :total="total" :size="10" @change="p=>{page=p;load()}"/></template>
<div v-if="choice" class="overlay" @click.self="choice=null"><form class="modal" @submit.prevent="add"><div class="section-title"><h2>{{choice.name}}</h2><button type="button" @click="choice=null">关闭</button></div><label v-for="f in choice.flavors" :key="f.name">{{f.name}}<select v-model="flavors[f.name]" required><option v-for="v in options(f)" :key="v" :value="v">{{v}}</option></select></label><p>{{money(choice.price)}}</p><button class="primary wide" :disabled="busy">加入购物车</button></form></div>
<div v-if="newAddress" class="overlay" @click.self="newAddress=false"><form class="modal" @submit.prevent="saveAddress"><div class="section-title"><h2>新增收货地址</h2><button type="button" @click="newAddress=false">关闭</button></div><label v-for="[k,t] in [['consignee','收货人'],['phone','手机号'],['provinceName','省份'],['cityName','城市'],['districtName','区县'],['detail','详细地址']]" :key="k">{{t}}<input v-model="address[k]" required :type="k==='phone'?'tel':'text'" :pattern="k==='phone'?'[0-9]{11}':undefined" maxlength="100"></label><button class="primary wide" :disabled="busy">保存地址</button></form></div><OrderDetail v-if="detail" :order="detail" @close="detail=null"/>
</template>
